/**
 * Binary-output kit — write tool-generated bytes (images, maps, exports) to a
 * configurable directory instead of dumping megabytes of base64 into a tool
 * result.
 *
 * Consolidates the duplicated trio in gemini (`images.ts#resolveOutputDir` /
 * `uniquePath` / `writeImage`) and flightaware (`shared.ts#resolveOutputDir` /
 * `writePng`): per-call dir → `<SVC>_OUTPUT_DIR` env → `~/Downloads/<name>`
 * (never the cwd — `/` under Claude Desktop, the user's repo under Claude
 * Code), non-overwriting
 * filenames, extension derived from the MIME type. The fleet convention (see
 * the mcp-fleet-builder skill) is that every binary-output tool uses this shape.
 */

import { existsSync, mkdirSync } from 'node:fs';
import { homedir } from 'node:os';
import { join } from 'node:path';

import { expandPath, readEnvVar, type EnvSource } from '../config/index.js';
import { McpToolError } from '../errors/index.js';
import { assertPathWithinRoots } from './confine.js';
import { assertSafeExtension, isSafeExtension, sanitizeBaseName, writeUniqueFileSync } from './write.js';

/** Options for {@link resolveOutputDir}. */
export interface ResolveOutputDirOptions {
  /** Where to read `envVar` from. Defaults to `process.env`. */
  env?: EnvSource;
  /** Confine the per-call directory to these roots (see below). */
  allowedRoots?: readonly string[];
  /**
   * The server's name, e.g. `'splitwise-mcp'`. When neither the per-call dir
   * nor `envVar` is set, the output goes to `~/Downloads/<name>` (created
   * `0700`). Without it, that case throws a config error naming `envVar`. Must
   * be a single path segment.
   */
  name?: string;
}

/**
 * Resolve the directory a binary-output tool should write into:
 * the per-call argument → the named env var → `~/Downloads/<name>` (when
 * `opts.name` is given) → a config error ({@link McpToolError}) naming the env
 * var. It **never** falls back to the current working directory: that is `/`
 * (unwritable) under Claude Desktop/.mcpb and the user's repo under Claude
 * Code (fleet audit 2026-09, cluster 12 — receipts and images landed there).
 * `~` and relative paths are expanded ({@link expandPath}) and the directory is
 * created recursively so the subsequent write can't ENOENT.
 *
 * `allowedRoots` (opt-in) confines the **per-call** directory — the value a
 * tool argument supplies — to those roots, checked through symlinks before
 * anything is created. The env var and the `name` fallback are operator
 * configuration and are not constrained.
 */
export function resolveOutputDir(
  perCall: string | undefined,
  envVar: string,
  opts: ResolveOutputDirOptions = {},
): string {
  const raw = perCall ?? readEnvVar(envVar, opts.env ? { env: opts.env } : {});
  if (!raw) return defaultOutputDir(envVar, opts.name);
  const dir = expandPath(raw);
  if (perCall !== undefined && opts.allowedRoots) {
    assertPathWithinRoots(dir, opts.allowedRoots);
    mkdirSync(dir, { recursive: true });
    // Re-check now it exists, in case a component was swapped for a symlink.
    assertPathWithinRoots(dir, opts.allowedRoots);
    return dir;
  }
  mkdirSync(dir, { recursive: true });
  return dir;
}

/** `~/Downloads/<name>` (created 0700), or a config error naming `envVar`. */
function defaultOutputDir(envVar: string, name: string | undefined): string {
  if (name === undefined) {
    throw new McpToolError(`No output directory is configured: ${envVar} is not set.`, {
      hint: `Set ${envVar} to a writable directory, or pass an output directory with the call.`,
    });
  }
  if (!name || name === '.' || name === '..' || /[/\\]/.test(name)) {
    throw new TypeError(`resolveOutputDir: name must be a single path segment, got ${JSON.stringify(name)}`);
  }
  const dir = join(homedir(), 'Downloads', name);
  mkdirSync(dir, { recursive: true, mode: 0o700 });
  return dir;
}

/**
 * A non-overwriting path for `base.ext` in `dir`: the bare name when free,
 * else `base-2.ext`, `base-3.ext`, … (gemini's numbering). `ext` is passed
 * without the dot and must pass {@link isSafeExtension} (a `TypeError`
 * otherwise). `base` is sanitized to a single path component so a `../…`
 * stem can't write outside `dir`.
 *
 * Check-then-use: the name can be taken (or a symlink planted there) between
 * this call and the caller's write. To write, prefer {@link writeUniqueFile} /
 * {@link writeBinaryOutput}, which claim the name with an exclusive create.
 */
export function uniquePath(dir: string, base: string, ext: string): string {
  assertSafeExtension(ext, 'uniquePath');
  const safe = sanitizeBaseName(base);
  const first = join(dir, `${safe}.${ext}`);
  if (!existsSync(first)) return first;
  for (let n = 2; ; n++) {
    const candidate = join(dir, `${safe}-${n}.${ext}`);
    if (!existsSync(candidate)) return candidate;
  }
}

/**
 * Extensions for the MIME types the fleet's binary tools emit — the union of
 * mcp-utils' own table and the ones gemini-mcp (`mediaExt`), concur-mcp
 * (`extensionForMime`) and splitwise-mcp (`extensionFor`) hand-rolled.
 */
const MIME_EXT: Record<string, string> = {
  'image/png': 'png',
  'image/jpeg': 'jpg',
  'image/jpg': 'jpg',
  'image/pjpeg': 'jpg',
  'image/webp': 'webp',
  'image/gif': 'gif',
  'image/heic': 'heic',
  'image/heif': 'heif',
  'image/avif': 'avif',
  'image/tiff': 'tif',
  'image/bmp': 'bmp',
  'image/svg+xml': 'svg',
  'application/pdf': 'pdf',
  'application/json': 'json',
  'application/zip': 'zip',
  'application/gzip': 'gz',
  'text/plain': 'txt',
  'text/csv': 'csv',
  'text/html': 'html',
  'text/calendar': 'ics',
  'audio/midi': 'mid',
  'audio/mpeg': 'mp3',
  'audio/mp3': 'mp3',
  'audio/wav': 'wav',
  'audio/wave': 'wav',
  'audio/x-wav': 'wav',
  'audio/ogg': 'ogg',
  'audio/webm': 'webm',
  'audio/mp4': 'm4a',
  'video/mp4': 'mp4',
  'video/quicktime': 'mov',
  'video/webm': 'webm',
};

/** A MIME subtype or URL extension short and plain enough to use as-is. */
const PLAIN_EXT = /^[a-z0-9]{1,5}$/;

/** Options for {@link extensionForMime}. */
export interface ExtensionForMimeOptions {
  /** The URL the bytes came from; its path's extension is the second fallback. */
  url?: string;
  /** What to return when nothing else fits. Default `'bin'`. Must pass {@link isSafeExtension}. */
  fallback?: string;
}

/**
 * The file extension (no dot) for a MIME type: the known-type table (`image/
 * jpeg` → `jpg`, `video/quicktime` → `mov`, …; parameters and case ignored),
 * else the subtype when it is a plain 1–5 character `[a-z0-9]` word (an `x-`
 * prefix dropped: `image/x-icon` → `icon`), else the extension of `opts.url`'s
 * path when it has a plain one, else `opts.fallback` (`'bin'`). The result
 * always passes {@link isSafeExtension}, so it can go straight to
 * `writeUniqueFile` / `writeBinaryOutput` — whatever the upstream's
 * Content-Type said (fleet-audit#1301, #1303).
 *
 * @throws {TypeError} when `opts.fallback` is not a safe extension.
 */
export function extensionForMime(mime: string | null | undefined, opts: ExtensionForMimeOptions = {}): string {
  const fallback = opts.fallback ?? 'bin';
  assertSafeExtension(fallback, 'extensionForMime');
  const type = (mime ?? '').split(';', 1)[0]!.trim().toLowerCase();
  const known = MIME_EXT[type];
  if (known !== undefined) return known;
  const slash = type.indexOf('/');
  const subtype = slash > 0 && type.indexOf('/', slash + 1) < 0 ? type.slice(slash + 1).replace(/^x-/, '') : '';
  if (PLAIN_EXT.test(subtype)) return subtype;
  if (opts.url !== undefined) {
    try {
      const fromUrl = /\.([a-z0-9]{1,5})$/i.exec(new URL(opts.url).pathname)?.[1]?.toLowerCase();
      if (fromUrl !== undefined && isSafeExtension(fromUrl)) return fromUrl;
    } catch {
      // Not a URL: no extension to read from it.
    }
  }
  return fallback;
}

/** Options for {@link writeBinaryOutput}. */
export interface WriteBinaryOutputOptions {
  /** Directory to write into (already resolved — see {@link resolveOutputDir}). */
  dir: string;
  /** Filename stem (no extension). */
  baseName: string;
  /** The bytes, base64-encoded (as returned by generation APIs). */
  base64: string;
  /** MIME type used to derive the extension when `extension` is not given. */
  mimeType?: string;
  /** Explicit extension (no dot); overrides the MIME lookup. Must pass {@link isSafeExtension}. */
  extension?: string;
  /** File mode for the new file (before umask), e.g. `0o600`. Default `0o666`. */
  mode?: number;
}

/**
 * Decode `base64` and write it to a **non-overwriting** file in `dir`, deriving
 * the extension from `extension` (which must pass {@link isSafeExtension}; a
 * `TypeError` otherwise) → {@link extensionForMime} of the MIME type (→
 * `'bin'`). Returns the
 * absolute path written. The caller returns that path from the tool result
 * (with an `inline` flag for base64 via `imageResult` when the user asks).
 *
 * Each candidate name is claimed with an exclusive, no-follow create
 * (`O_CREAT | O_EXCL | O_NOFOLLOW`) and the next name tried on EEXIST, so the
 * write is race-free and never goes through a symlink planted at the name —
 * previously a dangling symlink there looked "free" to `existsSync` and the
 * write created its target outside `dir`.
 */
export function writeBinaryOutput(opts: WriteBinaryOutputOptions): string {
  const ext = opts.extension ?? extensionForMime(opts.mimeType);
  return writeUniqueFileSync(opts.dir, opts.baseName, ext, Buffer.from(opts.base64, 'base64'), opts.mode);
}
